 "content": "from collections import Counter

def transform(grid):
    """Copy the non-background marker shape onto every matching background placement."""
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    marker = Counter(v for row in grid for v in row if v != background).most_common(1)[0][0]
    shape = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == marker]
    if not shape:
        return [row[:] for row in grid]
    r0 = min(r for r, c in shape)
    c0 = min(c for r, c in shape)
    shape = [(r-r0, c-c0) for r, c in shape]
    sh, sw = max(r for r, c in shape)+1, max(c for r, c in shape)+1
    out = [row[:] for row in grid]
    for r in range(h-sh+1):
        for c in range(w-sw+1):
            if all(grid[r+dr][c+dc] == background for dr, dc in shape):
                for dr, dc in shape:
                    out[r+dr][c+dc] = marker
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
